from collections import deque
def comps(g,color,bg=None):
    seen=set(); out=[]
    for i in range(len(g)):
        for j,a in enumerate(g[i]):
            if a==color and (i,j) not in seen:
                q=deque([(i,j)]);seen.add((i,j));cells=[]
                while q:
                    x,y=q.popleft();cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        xx,yy=x+dx,y+dy
                        if 0<=xx<len(g) and 0<=yy<len(g[0]) and g[xx][yy]==color and (xx,yy) not in seen:
                            seen.add((xx,yy));q.append((xx,yy))
                out.append(sorted(cells))
    return out
